<?php require 'config.php';$err=$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$n=trim($_POST['username']??'');$p=$_POST['password']??'';$c=$_POST['confirm']??'';
if(!preg_match('/^[A-Za-z0-9_.-]{3,30}$/',$n))$err='Username must be 3–30 characters.';
elseif(strlen($p)<8)$err='Password must be at least 8 characters.';
elseif($p!==$c)$err='Passwords do not match.';
else{try{$s=$pdo->prepare("INSERT INTO users(username,password,status,role) VALUES(?,?,'pending','user')");$s->execute([$n,password_hash($p,PASSWORD_DEFAULT)]);$msg='Registration successful. Wait for admin approval before signing in.';}catch(PDOException $e){$err='That username is already taken.';}}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register | Inventory System</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth"><main class="card"><div class="mark">IS</div><small>INVENTORY MANAGEMENT</small><h1>Create account</h1><p>Register and wait for administrator approval.</p><?php if($err):?><div class="alert"><?=$err?></div><?php endif;?><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Username</label><input name="username" required minlength="3" maxlength="30"><label>Password</label><input type="password" name="password" required minlength="8"><label>Confirm password</label><input type="password" name="confirm" required minlength="8"><button>Register</button></form><p class="center">Already registered? <a href="index.php">Sign in</a></p></main></body></html>